/** ESQUEMA DE LAS SUBPARTIDAS **/
CREATE COLUMN TABLE GC_COPLAIM."SPRTD" (
	"ID_SPRTD" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
	"DESCRIPCION" NVARCHAR(50) CS_STRING,
	"SUBPARTIDA" NVARCHAR(50) CS_STRING,
	"CREATED_AT" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
	"UPDATED_AT" TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

/** ESQUEMA DEL STOCK EN EL ECUAPAS - ADUANA **/
CREATE COLUMN TABLE GC_COPLAIM."ECUSTK" (
	"ID_ECUSTK" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
	"Item" INTEGER CS_INT DEFAULT 0,
	"Anexo" NVARCHAR(50) CS_STRING NOT NULL,
	"CodInsumo" NVARCHAR(150) CS_STRING NOT NULL,
	"SubPartida" NVARCHAR(100) CS_STRING NOT NULL,
	"SubPartida2" NVARCHAR(100) CS_STRING NOT NULL,
	"CodComple" NVARCHAR(50) CS_STRING NOT NULL,
	"CodSuple" NVARCHAR(50) CS_STRING NOT NULL,
	"Cantidad" DOUBLE CS_DOUBLE NOT NULL,
	"Unidad" NVARCHAR(20) CS_STRING NOT NULL,
	"Saldo" DOUBLE CS_DOUBLE NOT NULL,
	"DespRegu" DOUBLE CS_DOUBLE NOT NULL,
	"EgreDespRegu" DOUBLE CS_DOUBLE NOT NULL,
	"UsoGarantia" DOUBLE CS_DOUBLE DEFAULT 0,
	"FechaRegimen" LONGDATE CS_LONGDATE,
	"Tipo" NVARCHAR(20) CS_STRING NOT NULL,
	"CREATED_AT" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
	"UPDATED_AT" TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

/** ESQUEMA DE LAS FACTURAS RÉGIMEN 21 **/
CREATE COLUMN TABLE GC_COPLAIM."FR21" (
	"ID_FR21" NVARCHAR(50) CS_STRING PRIMARY KEY,
	"ID_AUTH" NVARCHAR(250) CS_STRING,
	"COMENTARIO" NVARCHAR(1000) CS_STRING,
	"FECHA1" NVARCHAR(25) CS_STRING,
	"FECHA2" NVARCHAR(25) CS_STRING,
	"SALDO" NVARCHAR(25) CS_STRING, -- SI - NO
	"ESTADO" NVARCHAR(15) CS_STRING DEFAULT 'I',
	"USER" NVARCHAR(50) CS_STRING NOT NULL,
	"CREATED_AT" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
	"UPDATED_AT" TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

/** ESQUEMA DE LAS FR21 - FACTURAS **/
CREATE COLUMN TABLE GC_COPLAIM."CAFR21" (
	"ID_CAFR21" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"ID_FR21" NVARCHAR(50) CS_STRING NOT NULL,
	"DOC_SAP" NVARCHAR(50) CS_STRING NOT NULL,
	"ntfc_no" NVARCHAR(50) CS_STRING PRIMARY KEY,
	"ntfc_de" NVARCHAR(50) CS_STRING NOT NULL,
	"CREATED_AT" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
	"UPDATED_AT" TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

ALTER TABLE "GC_COPLAIM"."CAFR21" ADD CONSTRAINT "CAFR21_FK_ID_FR21" FOREIGN KEY ("ID_FR21") REFERENCES "GC_COPLAIM"."FR21" ("ID_FR21")
	ON UPDATE CASCADE
	ON DELETE CASCADE;

/** ESQUEMA DE LAS FR21 - PRODUCTOS **/
CREATE COLUMN TABLE GC_COPLAIM."PDFR21" (
	"ID_PDFR21" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
	"ID_FR21" NVARCHAR(50) CS_STRING NOT NULL,
	"ntfc_no" NVARCHAR(50) CS_STRING NOT NULL,
	"SUBPARTIDA" NVARCHAR(50) CS_STRING NOT NULL,
	"CODE_PT" NVARCHAR(50) CS_STRING NOT NULL,
	"DESCRIPCION" NVARCHAR(350) CS_STRING NOT NULL,
	"U_MEDIDA" NVARCHAR(50) CS_STRING NOT NULL,
	"CANTIDAD" INTEGER CS_INT NOT NULL,
   "GR_ALM" INTEGER CS_INT NOT NULL,
   "FLAUTA" NVARCHAR(10) NOT NULL,
   "INDICE" INTEGER CS_INT DEFAULT 0 NOT NULL,
	"CREATED_AT" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
	"UPDATED_AT" TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

ALTER TABLE "GC_COPLAIM"."PDFR21" ADD CONSTRAINT "PDFR21_FK_NTFC_NO" FOREIGN KEY ("ntfc_no") REFERENCES "GC_COPLAIM"."CAFR21" ("ntfc_no")
	ON UPDATE CASCADE
	ON DELETE CASCADE;

/** ESQUEMA DE LAS FR21 - MATERIA PRIMA **/
CREATE COLUMN TABLE GC_COPLAIM."MPFR21" (
	"ID_MPFR21" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
	"ID_FR21" NVARCHAR(50) CS_STRING NOT NULL,
	"ITM_FR21" INTEGER CS_INT NOT NULL,
	"CODE_PT" NVARCHAR(50) CS_STRING NOT NULL,
	"ntfc_no" NVARCHAR(50) CS_STRING NOT NULL,
	"DAI" NVARCHAR(100) CS_STRING NOT NULL,
	"COD_ADUANA" NVARCHAR(50) CS_STRING NOT NULL,
	"SUBPARTIDA" NVARCHAR(50) CS_STRING NOT NULL,
	"DESCRIPCION" NVARCHAR(250) CS_STRING NOT NULL,
	"U_MEDIDA" NVARCHAR(50) CS_STRING NOT NULL,
	"CANTIDAD" DOUBLE CS_DOUBLE NOT NULL,
	"DESPERDICIO" DOUBLE CS_DOUBLE NOT NULL,
	"MERMA" DOUBLE CS_DOUBLE NOT NULL,
	"TOTAL" DOUBLE CS_DOUBLE NOT NULL,
	"CREATED_AT" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
	"UPDATED_AT" TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

ALTER TABLE "GC_COPLAIM"."MPFR21" ADD CONSTRAINT "MPFR21_FK_NTFC_NO" FOREIGN KEY ("ntfc_no") REFERENCES "GC_COPLAIM"."CAFR21" ("ntfc_no")
	ON UPDATE CASCADE
	ON DELETE CASCADE;